// Every GROQ query the site uses. Types are generated by Sanity TypeGen into ./types.ts
// (`npm --prefix studio run typegen`). Editorial fields (needsReview, reviewNote) are never queried.
import { defineQuery } from 'next-sanity';

// ── Fragments ────────────────────────────────────────────────────────────────
const image = /* groq */ `
  asset->{ _id, url, metadata { lqip, dimensions { width, height } } },
  alt, hotspot, crop
`;

const seo = /* groq */ `seo { title, description, shareImage { ${image} } }`;

const richText = /* groq */ `[]{
  ...,
  _type == "figure" => { _key, _type, label, textEquivalent, image { ${image} } },
  markDefs[]{ ... }
}`;

const projectCard = /* groq */ `
  _id, code, title, "slug": slug.current, status, layout, featured, summary, tools,
  stageCoverage { commit, build, test, ship, run, observe },
  coverImage { ${image} }
`;

const noteCard = /* groq */ `
  _id, code, title, "slug": slug.current, date, summary, tags,
  category->{ title, "slug": slug.current },
  project->{ code, title, "slug": slug.current },
  coverImage { ${image} },
  "hasDebugSteps": defined(debugSteps)
`;

// ── Singletons ───────────────────────────────────────────────────────────────
export const SETTINGS_QUERY = defineQuery(`*[_id == "siteSettings"][0]{
  name, resumeName, location, footerTagline, resumeHeadline, resumeSummary,
  headlineLabel, heroLine, heroParagraph,
  summaryCells[]{ _key, label, value },
  openToRoles, rolesWanted, workPreference, availability,
  email, linkedinUrl, githubUrl,
  socials[]{ _key, label, url },
  "resumeUrl": resumeFile.asset->url,
  ${seo}
}`);

export const PAGE_COPY_QUERY = defineQuery(`*[_id == "pageCopy"][0]{
  work, notes, journey, experience, skills, infrastructure, contact, terminal, resume, notFound
}`);

export const HOME_QUERY = defineQuery(`{
  "home": *[_id == "homePage"][0]{
    featuredProject->{ ${projectCard}, recruiterSummary },
    sections[]{ _key, section, visible }
  },
  "otherFeatured": *[_type == "project" && defined(slug.current) && featured == true
    && _id != *[_id == "homePage"][0].featuredProject._ref] | order(orderRank) { ${projectCard} },
  "infraTeaser": *[_type == "infraNode" && state == "live"] | order(orderRank) { _id, kicker, name, category },
  "siteStatus": *[_id == "siteStatus"][0] { status, checkedAt, uptime },
  "recentMilestones": *[_type == "milestone" && planned != true] | order(sortDate desc)[0...4] {
    _id, title, dateLabel, latest
  },
  "nextMilestone": *[_type == "milestone" && planned == true] | order(orderRank asc)[0] { title },
  "latestNote": *[_type == "note" && defined(slug.current)] | order(date desc)[0] { ${noteCard} }
}`);

export const SITE_STATUS_QUERY = defineQuery(
  `*[_id == "siteStatus"][0]{ status, checkedAt, uptime }`,
);

// ── Projects ─────────────────────────────────────────────────────────────────
export const PROJECTS_QUERY = defineQuery(
  `*[_type == "project" && defined(slug.current)] | order(orderRank) { ${projectCard} }`,
);

export const PROJECT_SLUGS_QUERY = defineQuery(
  `*[_type == "project" && defined(slug.current)]{ "slug": slug.current }`,
);

/** Minimal project shape for the footer sitemap. */
export const FOOTER_PROJECTS_QUERY = defineQuery(
  `*[_type == "project" && defined(slug.current)] | order(orderRank) { title, "slug": slug.current }`,
);

export const PROJECT_QUERY = defineQuery(`*[_type == "project" && slug.current == $slug][0]{
  ${projectCard},
  recruiterSummary, role, started, _updatedAt,
  evidence[]{ _key, label, url },
  body${richText},
  sections[]{ _key, heading, navLabel, body${richText} },
  ${seo},
  "previous": *[_type == "project" && defined(slug.current) && orderRank < ^.orderRank]
    | order(orderRank desc)[0]{ code, title, "slug": slug.current },
  "next": *[_type == "project" && defined(slug.current) && orderRank > ^.orderRank]
    | order(orderRank asc)[0]{ code, title, "slug": slug.current }
}`);

// ── Blog ─────────────────────────────────────────────────────────────────────
export const NOTES_QUERY = defineQuery(
  `*[_type == "note" && defined(slug.current)] | order(date desc) { ${noteCard} }`,
);

export const NOTE_SLUGS_QUERY = defineQuery(
  `*[_type == "note" && defined(slug.current)]{ "slug": slug.current }`,
);

export const NOTE_QUERY = defineQuery(`*[_type == "note" && slug.current == $slug][0]{
  ${noteCard},
  body${richText},
  debugSteps {
    symptomLine, causeLine, fixLine, symptom,
    errorLog { filename, language, code },
    checks[]{ _key, command, result, outcome },
    rootCause, explanation, fix { before, after }, verification, prevention
  },
  ${seo}
}`);

export const NOTE_CATEGORIES_QUERY = defineQuery(
  `*[_type == "noteCategory"] | order(title) { _id, title, "slug": slug.current }`,
);

// ── Journey, experience, skills, certifications, infrastructure ─────────────
export const MILESTONES_QUERY = defineQuery(`*[_type == "milestone"] | order(orderRank) {
  _id, title, category, dateLabel, sortDate, planned, latest,
  link {
    label,
    "href": coalesce(
      path,
      select(
        reference->_type == "project" => "/work/" + reference->slug.current,
        reference->_type == "note" => "/notes/" + reference->slug.current
      )
    )
  }
}`);

export const ROLES_QUERY = defineQuery(`*[_type == "role"] | order(startDate desc) {
  _id, kind, title, organisation, location, startDate, endDate, yearsOnly,
  context, highlights, alsoInRole, stack, infrastructureNote
}`);

export const SKILLS_QUERY = defineQuery(`*[_type == "skill"] | order(orderRank) {
  _id, name, group, tier, usageNote,
  usedIn[]->{ _id, _type, title, code, "slug": slug.current }
}`);

export const CREDENTIALS_QUERY = defineQuery(`*[_type == "credential"] | order(issued desc) {
  _id, name, issuer, issued, credentialId, verifyUrl, badge { ${image} }
}`);

export const INFRA_QUERY = defineQuery(`*[_type == "infraNode"] | order(orderRank) {
  _id, kicker, name, sub, category, state, role,
  connections[]{ _key, label, type, "target": target._ref }
}`);

// ── SEO: sitemap and feed ────────────────────────────────────────────────────
// Planned projects have no public page yet, so they stay out of the sitemap.
export const SITEMAP_QUERY = defineQuery(`{
  "projects": *[_type == "project" && defined(slug.current) && status != "planned"] | order(orderRank) {
    "slug": slug.current, _updatedAt
  },
  "notes": *[_type == "note" && defined(slug.current)] | order(date desc) {
    "slug": slug.current, date, _updatedAt
  }
}`);

export const FEED_QUERY =
  defineQuery(`*[_type == "note" && defined(slug.current)] | order(date desc) {
  title, "slug": slug.current, date, summary, "category": category->title
}`);
